DROP POLICY IF EXISTS "Users can append their own audit events" ON public.security_audit_log; REVOKE INSERT ON public.security_audit_log FROM authenticated; GRANT ALL ON public.security_audit_log TO service_role;
DROP POLICY IF EXISTS ppm_ai_create ON public.app_settings; DROP POLICY IF EXISTS ppm_ai_update ON public.app_settings; REVOKE INSERT,UPDATE,DELETE ON public.app_settings FROM authenticated;
DROP POLICY IF EXISTS "Superadmins can read application settings" ON public.app_settings;
DROP POLICY IF EXISTS "Superadmins can create portal settings" ON public.portal_settings; DROP POLICY IF EXISTS "Superadmins can update portal settings" ON public.portal_settings;
CREATE POLICY ppm_portal_create ON public.portal_settings FOR INSERT TO authenticated WITH CHECK(id='portal' AND updated_by=auth.uid() AND public.ppm_tem_papel('administrador_pmo'));
CREATE POLICY ppm_portal_update ON public.portal_settings FOR UPDATE TO authenticated USING(id='portal' AND public.ppm_tem_papel('administrador_pmo')) WITH CHECK(id='portal' AND updated_by=auth.uid() AND public.ppm_tem_papel('administrador_pmo'));
CREATE OR REPLACE FUNCTION public.ppm_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h jsonb; BEGIN BEGIN h:=coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}'); EXCEPTION WHEN OTHERS THEN h:='{}'; END; IF auth.uid() IS NOT NULL THEN INSERT INTO public.security_audit_log(user_id,event_type,entity_type,entity_id,result,context) VALUES(auth.uid(),CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'UPDATE' THEN 'update' ELSE 'delete' END,TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id'),'success',jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,'roles',(SELECT jsonb_agg(papel) FROM public.ppm_papeis WHERE user_id=auth.uid()),'user_agent',h->>'user-agent','ip',h->>'x-forwarded-for')); END IF; RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER ppm_roles_audit AFTER INSERT OR UPDATE OR DELETE ON public.ppm_papeis FOR EACH ROW EXECUTE FUNCTION public.ppm_auditar();
CREATE TRIGGER ppm_users_audit AFTER INSERT OR UPDATE OR DELETE ON public.ppm_usuarios FOR EACH ROW EXECUTE FUNCTION public.ppm_auditar();